// The errors Intl throws for each misuse go-quickjs checks, one line each,
// "name<TAB>ErrorType: message". Run by Node, it writes
// testdata/intl_errors_node.txt:
//
//	node testdata/intl_errors_node.js > testdata/intl_errors_node.txt
//
// and TestIntlErrorsMatchNode runs it here and compares. Left out is
// new Intl.Locale("en", {variants: "a"}), which Node accepts and test262's
// constructor-options-variants-invalid refuses, as go-quickjs does.
const getter = (C, p) => Object.getOwnPropertyDescriptor(C.prototype, p).get;
const cases = {
  "locale-not-tag": () => Intl.getCanonicalLocales("en_US"),
  "locale-bad-type": () => Intl.getCanonicalLocales([1]),
  "supportedValuesOf-key": () => Intl.supportedValuesOf("units"),
  "option-string-value": () => new Intl.NumberFormat("en", { style: "bogus" }),
  "option-matcher-value": () => new Intl.NumberFormat("en", { localeMatcher: "bogus" }),
  "option-type-value": () => new Intl.NumberFormat("en", { numberingSystem: "a" }),
  "option-calendar-value": () => new Intl.DateTimeFormat("en", { calendar: "x!" }),
  "options-not-object-strict": () => new Intl.Segmenter("en", 5),
  "options-null": () => new Intl.NumberFormat("en", null),
  "coll-options-null": () => new Intl.Collator("en", null),
  "dtf-options-null": () => new Intl.DateTimeFormat("en", null),
  "rtf-options-null": () => new Intl.RelativeTimeFormat("en", null),
  "df-options-5": () => new Intl.DurationFormat("en", 5),
  "digits-range-minint": () => new Intl.NumberFormat("en", { minimumIntegerDigits: 0 }),
  "digits-range-maxfrac": () => new Intl.NumberFormat("en", { maximumFractionDigits: 101 }),
  "digits-range-minsig": () => new Intl.NumberFormat("en", { minimumSignificantDigits: 0 }),
  "digits-range-maxsig": () => new Intl.NumberFormat("en", { minimumSignificantDigits: 5, maximumSignificantDigits: 3 }),
  "digits-frac-order": () => new Intl.NumberFormat("en", { minimumFractionDigits: 5, maximumFractionDigits: 3 }),
  "rounding-increment-value": () => new Intl.NumberFormat("en", { roundingIncrement: 3 }),
  "rounding-increment-sig": () => new Intl.NumberFormat("en", { roundingIncrement: 5, maximumSignificantDigits: 2 }),
  "rounding-increment-frac": () => new Intl.NumberFormat("en", { roundingIncrement: 5, minimumFractionDigits: 1, maximumFractionDigits: 2 }),
  "use-grouping-value": () => new Intl.NumberFormat("en", { useGrouping: "sometimes" }),
  "currency-missing": () => new Intl.NumberFormat("en", { style: "currency" }),
  "currency-bad": () => new Intl.NumberFormat("en", { currency: "US" }),
  "unit-missing": () => new Intl.NumberFormat("en", { style: "unit" }),
  "unit-bad": () => new Intl.NumberFormat("en", { style: "unit", unit: "furlong" }),
  "nf-receiver": () => Intl.NumberFormat.prototype.formatToParts.call({}, 1),
  "nf-format-receiver": () => getter(Intl.NumberFormat, "format").call({}),
  "nf-format-5": () => getter(Intl.NumberFormat, "format").call(5),
  "nf-resolved-receiver": () => Intl.NumberFormat.prototype.resolvedOptions.call({}),
  "nf-resolved-arr": () => Intl.NumberFormat.prototype.resolvedOptions.call([]),
  "nf-range": () => Intl.NumberFormat.prototype.formatRange.call({}, 0, 1),
  "nf-range-undefined": () => new Intl.NumberFormat("en").formatRange(1),
  "nf-range-undef-start": () => new Intl.NumberFormat("en").formatRange(undefined, 1),
  "nf-range-nan": () => new Intl.NumberFormat("en").formatRange(NaN, 1),
  "nf-range-nan-end": () => new Intl.NumberFormat("en").formatRange(1, NaN),
  "pr-no-new": () => Intl.PluralRules(),
  "pr-receiver": () => Intl.PluralRules.prototype.select.call({}, 1),
  "pr-resolved": () => Intl.PluralRules.prototype.resolvedOptions.call(5),
  "pr-range-undefined": () => new Intl.PluralRules("en").selectRange(1),
  "pr-range-nan": () => new Intl.PluralRules("en").selectRange(NaN, 1),
  "pr-range-nan-end": () => new Intl.PluralRules("en").selectRange(1, NaN),
  "coll-receiver": () => Intl.Collator.prototype.resolvedOptions.call({}),
  "coll-compare-receiver": () => getter(Intl.Collator, "compare").call({}),
  "coll-co": () => new Intl.Collator("en", { collation: "a" }),
  "lf-no-new": () => Intl.ListFormat(),
  "lf-receiver": () => Intl.ListFormat.prototype.format.call({}, []),
  "lf-not-string": () => new Intl.ListFormat("en").format([1]),
  "lf-yield-obj": () => new Intl.ListFormat("en").format([{}]),
  "lf-yield-sym": () => new Intl.ListFormat("en").format([Symbol("x")]),
  "dn-no-new": () => Intl.DisplayNames(),
  "dn-no-options": () => new Intl.DisplayNames("en"),
  "dn-no-type": () => new Intl.DisplayNames("en", {}),
  "dn-receiver": () => Intl.DisplayNames.prototype.of.call({}, "en"),
  "dn-region": () => new Intl.DisplayNames("en", { type: "region" }).of("ABC"),
  "dn-script": () => new Intl.DisplayNames("en", { type: "script" }).of("La"),
  "dn-currency": () => new Intl.DisplayNames("en", { type: "currency" }).of("US"),
  "dn-language": () => new Intl.DisplayNames("en", { type: "language" }).of("en-u-ca-gregory"),
  "dn-language-bad": () => new Intl.DisplayNames("en", { type: "language" }).of("en_US"),
  "dn-calendar": () => new Intl.DisplayNames("en", { type: "calendar" }).of("ab"),
  "dn-field": () => new Intl.DisplayNames("en", { type: "dateTimeField" }).of("fortnight"),
  "rtf-no-new": () => Intl.RelativeTimeFormat(),
  "rtf-receiver": () => Intl.RelativeTimeFormat.prototype.format.call({}, 1, "day"),
  "rtf-infinite": () => new Intl.RelativeTimeFormat("en").format(Infinity, "day"),
  "rtf-unit": () => new Intl.RelativeTimeFormat("en").format(1, "fortnight"),
  "rtf-parts-unit": () => new Intl.RelativeTimeFormat("en").formatToParts(1, "x"),
  "rtf-parts-inf": () => new Intl.RelativeTimeFormat("en").formatToParts(NaN, "day"),
  "seg-no-new": () => Intl.Segmenter(),
  "seg-receiver": () => Intl.Segmenter.prototype.segment.call({}, "a"),
  "seg-gran": () => new Intl.Segmenter("en", { granularity: "line" }),
  "segments-receiver": () => new Intl.Segmenter("en").segment("a").containing.call({}, 0),
  "segs-iter": () => new Intl.Segmenter().segment("a")[Symbol.iterator].call({}),
  "seg-iter-receiver": () => new Intl.Segmenter("en").segment("a")[Symbol.iterator]().next.call({}),
  "df-no-new": () => Intl.DurationFormat(),
  "df-receiver": () => Intl.DurationFormat.prototype.format.call({}, {}),
  "df-words-after-numeric": () => new Intl.DurationFormat("en", { hours: "numeric", minutes: "long" }),
  "df-display-always-fraction": () => new Intl.DurationFormat("en", { seconds: "numeric", milliseconds: "numeric", millisecondsDisplay: "always" }),
  "df-string": () => new Intl.DurationFormat("en").format("P1X"),
  "df-string-designator": () => new Intl.DurationFormat("en").format("PT"),
  "df-not-object": () => new Intl.DurationFormat("en").format(5),
  "df-fraction": () => new Intl.DurationFormat("en").format({ hours: 1.5 }),
  "df-empty": () => new Intl.DurationFormat("en").format({}),
  "df-too-long": () => new Intl.DurationFormat("en").format({ seconds: 2 ** 53 }),
  "df-mixed-sign": () => new Intl.DurationFormat("en").format({ hours: 1, minutes: -1 }),
  "df-fractional-digits": () => new Intl.DurationFormat("en", { fractionalDigits: 10 }),
  "dtf-receiver": () => Intl.DateTimeFormat.prototype.formatToParts.call({}, 0),
  "dtf-format-receiver": () => getter(Intl.DateTimeFormat, "format").call({}),
  "dtf-resolved": () => Intl.DateTimeFormat.prototype.resolvedOptions.call({}),
  "dtf-range": () => Intl.DateTimeFormat.prototype.formatRange.call({}, 0, 1),
  "dtf-style-and-field": () => new Intl.DateTimeFormat("en", { dateStyle: "short", hour: "numeric" }),
  "dtf-hc": () => new Intl.DateTimeFormat("en", { hourCycle: "h13" }),
  "dtf-fsd": () => new Intl.DateTimeFormat("en", { fractionalSecondDigits: 4 }),
  "dtf-invalid-date": () => new Intl.DateTimeFormat("en").format(NaN),
  "dtf-zone": () => new Intl.DateTimeFormat("en", { timeZone: "Mars/Base" }),
  "dtf-timezone-empty": () => new Intl.DateTimeFormat("en", { timeZone: "" }),
  "dtf-range-undefined": () => new Intl.DateTimeFormat("en").formatRange(0),
  "dtf-range-undef-start": () => new Intl.DateTimeFormat("en").formatRange(undefined, 0),
  "dtf-range-nan": () => new Intl.DateTimeFormat("en").formatRange(NaN, 0),
  "dtf-range-types": () => new Intl.DateTimeFormat("en").formatRange(Temporal.PlainDate.from("2024-01-01"), 0),
  "dtf-zoned": () => new Intl.DateTimeFormat("en").format(Temporal.ZonedDateTime.from("2024-01-01T00:00[UTC]")),
  "dtf-calendar": () => new Intl.DateTimeFormat("en", { calendar: "hebrew" }).format(Temporal.PlainDate.from("2024-01-01[u-ca=japanese]")),
  "dtf-temporal-style": () => new Intl.DateTimeFormat("en", { timeStyle: "short" }).format(Temporal.PlainDate.from("2024-01-01")),
  "date-tolocaledatestring-style": () => new Date(0).toLocaleDateString("en", { timeStyle: "short" }),
  "date-tolocaletimestring-style": () => new Date(0).toLocaleTimeString("en", { dateStyle: "short" }),
  "date-tolocaledatestring-bad": () => new Date(0).toLocaleDateString("en_US"),
  "loc-no-new": () => Intl.Locale("en"),
  "loc-bad-type": () => new Intl.Locale(5),
  "loc-empty": () => new Intl.Locale(""),
  "loc-undefined": () => new Intl.Locale(),
  "loc-bad-tag": () => new Intl.Locale("en_US"),
  "loc-language": () => new Intl.Locale("en", { language: "e1" }),
  "loc-script": () => new Intl.Locale("en", { script: "La" }),
  "loc-region": () => new Intl.Locale("en", { region: "ABCD" }),
  "loc-calendar": () => new Intl.Locale("en", { calendar: "x" }),
  "loc-receiver": () => Intl.Locale.prototype.maximize.call({}),
  "loc-basename": () => getter(Intl.Locale, "baseName").call({}),
  "loc-tostring": () => Intl.Locale.prototype.toString.call({}),
  "loc-calendars": () => Intl.Locale.prototype.getCalendars.call({}),
  "tolocalestring-bad-locale": () => (1).toLocaleString("en_US"),
  "localecompare-bad-locale": () => "a".localeCompare("b", "en_US"),
};
for (const [name, fn] of Object.entries(cases)) {
  let line = `${name}\t(no error)`;
  try {
    fn();
  } catch (e) {
    line = `${name}\t${e.name}: ${e.message}`;
  }
  console.log(line);
}
